// ---- Events ----

/** Events sent by the Go side. Subscribe with `events.name.on(listener)`. */
export const events = {
  /** NowPlayingChanged tells every window what plays. */
  nowPlaying: event<NowPlaying>("nowPlaying"),
  /** PlayerCommandSent asks the main window's player to do something. */
  playerCommand: event<PlayerCommand>("playerCommand"),
  /** SettingsChanged tells every window the new settings. */
  settingsChanged: event<Settings>("settingsChanged"),
  /** AddonsChanged tells every window the add-ons changed. */
  addonsChanged: event<Inventory>("addonsChanged"),
  /** AccountsChanged tells every window the user signed in or out. */
  accountsChanged: event<AccountsStatus>("accountsChanged"),
  /**
   * NavigateRequested asks the main window to show a page, such as
   * "/search?q=daft%20punk".
   */
  navigate: event<string>("navigate"),
  /**
   * UpdatesChanged tells every window the update preferences changed, after
   * a check too.
   */
  updatesChanged: event<UpdateStatus>("updatesChanged"),
} as const;
